<?php
declare(strict_types=1);
require_once __DIR__.'/../../Services/authService.php';
try{$user=auth_user_from_cookie();}catch(Throwable $e){http_response_code(503);exit('Service indisponible.');}
if(!$user){header('Location: index.php?mode=login');exit;}
$currentPage='messages';$pageTitle='Messages';$conversation=(int)($_GET['conversation']??0);require __DIR__.'/../components/header.php';require __DIR__.'/../components/navBar.php';
$q=db()->prepare('SELECT c.Id_conversations,MAX(m.created_at) last_message,GROUP_CONCAT(DISTINCT CONCAT(u.first_name," ",u.name) SEPARATOR ", ") participants FROM lier mine JOIN Conversations c ON c.Id_conversations=mine.Id_conversations LEFT JOIN Messages m ON m.Id_conversations=c.Id_conversations JOIN lier peers ON peers.Id_conversations=c.Id_conversations JOIN Users u ON u.Id_users=peers.Id_users AND u.Id_users<>:user WHERE mine.Id_users=:user2 GROUP BY c.Id_conversations ORDER BY last_message DESC');$q->execute(['user'=>$user['Id_users'],'user2'=>$user['Id_users']]);$conversations=$q->fetchAll();if(!$conversation&&$conversations)$conversation=(int)$conversations[0]['Id_conversations'];
?>
<section class="p-4 md:p-8 h-[calc(100vh-76px)]"><div class="h-full max-w-6xl mx-auto bg-white border rounded-2xl overflow-hidden grid md:grid-cols-[280px_1fr]"><aside class="border-r overflow-y-auto"><h1 class="p-5 text-xl font-bold">Discussions</h1><?php foreach($conversations as $item): ?><a class="block border-t p-4 hover:bg-teal-50 <?= $conversation===(int)$item['Id_conversations']?'bg-teal-50':'' ?>" href="index.php?page=messages&amp;conversation=<?= (int)$item['Id_conversations'] ?>"><b><?= htmlspecialchars($item['participants'],ENT_QUOTES,'UTF-8') ?></b><small class="block text-slate-500 mt-1"><?= htmlspecialchars((string)($item['last_message']??'Nouvelle discussion'),ENT_QUOTES,'UTF-8') ?></small></a><?php endforeach; ?></aside><div class="min-w-0 flex flex-col"><div class="border-b p-4 font-semibold">Conversation UniFlow</div><div id="chatMessages" class="flex-1 overflow-y-auto p-5 space-y-3 bg-slate-50" aria-live="polite"></div><form id="chatForm" class="border-t p-4 flex gap-2"><input name="content" required maxlength="2000" class="flex-1 min-w-0 border rounded-xl px-4 py-3" placeholder="Écrire un message…"><button class="bg-teal-700 text-white rounded-xl px-5">Envoyer</button></form></div></div></section>
<script>
const conversationId=<?= (int)$conversation ?>;const ownId=<?= (int)$user['Id_users'] ?>;const box=document.getElementById('chatMessages');
async function refreshChat(){if(!conversationId)return;try{const data=await(await fetch('index.php?api=messages-list&conversation='+conversationId)).json();box.replaceChildren(...data.messages.map(m=>{const row=document.createElement('div');row.className='max-w-[80%] rounded-2xl px-4 py-3 '+(Number(m.Id_users)===ownId?'ml-auto bg-teal-700 text-white':'bg-white border');const who=document.createElement('small');who.className='block opacity-70';who.textContent=m.first_name+' · '+m.created_at;const msg=document.createElement('p');msg.textContent=m.content;row.append(who,msg);return row}));box.scrollTop=box.scrollHeight}catch{}}
document.getElementById('chatForm').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.currentTarget);form.append('conversation',conversationId);const data=await(await fetch('index.php?api=message-send',{method:'POST',body:form})).json();if(data.ok){e.currentTarget.reset();refreshChat()}});refreshChat();setInterval(refreshChat,2500);
</script>
<?php require __DIR__.'/../components/footer.php'; ?>
